void transpose(const float* a, float* b, size_t n) {
  constexpr size_t B = 32;  // 32x32 floats = 4KB per tile, two tiles fit in L1
  for (size_t ii = 0; ii < n; ii += B)
    for (size_t jj = 0; jj < n; jj += B) {
      const size_t iend = std::min(ii + B, n);
      const size_t jend = std::min(jj + B, n);
      for (size_t i = ii; i < iend; ++i)
        for (size_t j = jj; j < jend; ++j)
          b[j * n + i] = a[i * n + j];
    }
}
